source('R/00_setup.R')
d <- readr::read_csv(file.path(root_dir,'data/source_data/Fig5ab_distribution_cells.csv'),show_col_types=FALSE) |> dplyr::filter(EndpointSet=='All endpoints')
short <- c('EMBRYO'='Embryo','LARVA'='Larva','SETTLEMENT/METAMORPHOSIS'='Settl./met.','JUVENILE/ADULT'='Juv./adult')
shared_range <- range(d$yi,na.rm=TRUE)
p <- ggplot2::ggplot(d,ggplot2::aes(ObservedStage,yi,colour=StressorLabel)) + ggplot2::geom_hline(yintercept=0,linetype=2,linewidth=.25,colour='#4A417A') + ggplot2::geom_segment(ggplot2::aes(xend=ObservedStage,y=0,yend=yi),linewidth=.35,alpha=.38,position=ggplot2::position_jitter(width=.055,height=0,seed=15)) + ggplot2::geom_point(position=ggplot2::position_jitter(width=.055,height=0,seed=15),size=1.15,alpha=.88) + ggplot2::facet_wrap(~StressorLabel,nrow=1,labeller=ggplot2::as_labeller(c('Acidification'='Acidification','Warming'='Warming','Warming + acidification'='Combined'))) + ggplot2::scale_colour_manual(values=driver_pal,guide='none') + ggplot2::scale_x_discrete(labels=short) + ggplot2::scale_y_continuous(transform=scales::pseudo_log_trans(sigma=.15),breaks=c(-10,-4,-1,0,1,4,10),name='Study-cell directional lnRR (asinh axis)') + ggplot2::coord_cartesian(ylim=shared_range) + ggplot2::labs(x=NULL,caption='Lollipop: stem from zero to each observed inverse-variance aggregated study-cell response; endpoint dots are actual study cells; no inferential test is added.') + theme_publication(base_size=8) + theme(plot.caption=ggplot2::element_text(size=6.5,hjust=0),panel.spacing=grid::unit(3,'mm'),axis.text.x=ggplot2::element_text(size=6.5))
save_figure(p,'figures/main/Fig5a_lollipop_distribution',210,105,dpi=800)
